@router.post({{path}}, response_model=ParentRead, status_code=201)
def create_parent(data: ParentCreate, db: Annotated[Session, Depends(session_provider)]) -> Parent:
    """Create parent."""
    row = Parent(**model_values(data))
    db.add(row)
    try:
        db.commit()
    except IntegrityError as exc:
        integrity_failure(db, exc, False)
    db.refresh(row)
    return row
